// Step 1: Validasi ZIP dan Masking Secret
const binaryData = $input.item.binary?.file;
if (!binaryData) {
  return [{ json: { error: 'No ZIP file uploaded' } }];
}

// Simulasi pengecekan magic bytes dan batas 10MB
const maxBytes = 10 * 1024 * 1024;
if (binaryData.fileSize > maxBytes) {
  return [{ json: { error: 'File exceeds 10 MB limit' } }];
}

return [{
  json: {
    status: 'VALIDATED',
    fileName: binaryData.fileName || 'project.zip',
    sizeBytes: binaryData.fileSize,
    agentTarget: $input.item.json.body?.agentTarget || 'Generic',
    context: $input.item.json.body?.context || {}
  }
}];

// Step 4: Parse Hasil & Format Prompt Khusus untuk Coding Agent
const report = $input.item.json.report;
const agentTarget = $input.item.json.agentTarget || 'Cursor';

const formattedFindings = (report.findings || []).map(f => ({
  id: f.id,
  title: f.title,
  severity: f.severity,
  area: f.area,
  file: f.location?.file,
  line: f.location?.line,
  remediationPrompt: f.remediationPrompt
}));

return [{
  json: {
    auditSummary: report.summary,
    counts: report.countsBySeverity,
    scorecard: report.scorecard,
    secretsToRotate: report.secretsToRotate,
    findings: formattedFindings,
    readyPromptsCount: formattedFindings.length
  }
}];
